                                    "$ref": "#/$defs/IndicatorOperand"
                                },
                                {
                                    "$ref": "#/$defs/PriceOperand"
                                },
                                {
                                    "$ref": "#/$defs/ConstantOperand"
                                }
                            ],
                            "title": "Upper"
                        }
                    },
                    "required": [
                        "op",
                        "value",
                        "lower",
                        "upper"
                    ],
                    "title": "BetweenCondition",
                    "type": "object"
                },
                "CompareCondition": {
                    "additionalProperties": false,
                    "properties": {
                        "left": {
                            "oneOf": [
